insert into public.zones ("id", "name", "theme", "boss_name", "base_hp", "lore") values
  (1, 'The Slums of Nafs', 'Laziness, small sins', 'Gluttony Hound', 50, 'Where every soul first wakes. The whispers are soft here, but constant.'),
  (2, 'The Desert of Delay', 'Procrastination', 'The Slack King', 58, 'A burning plain where tomorrow never comes.'),
  (3, 'The Valley of Whispers', 'Waswas', 'Whisper Warlock', 66, 'Every stone speaks. Every voice doubts.'),
  (4, 'The Fortress of Arrogance', 'Pride, ego', 'The Proud General', 76, 'Its walls are made of self-praise.'),
  (5, 'The Sea of Distraction', 'Social media, phones', 'The Endless Feeder', 88, 'An infinite scroll of black water.'),
  (6, 'The Cave of Sleep', 'Oversleeping', 'The Lethargy Beast', 101, 'The sun rises outside. You do not.'),
  (7, 'The Bazaar of Greed', 'Money, materialism', 'The Golden Serpent', 116, 'Everything is for sale. Including you.'),
  (8, 'The Arena of Anger', 'Rage, temper', 'The Fury Titan', 133, 'Blood on the sand. Fury in the heart.'),
  (9, 'The Garden of Lust', 'Lower desires', 'The Nafs Serpent', 153, 'Beautiful. Poisonous. Yours.'),
  (10, 'The Library of Doubt', 'Weak iman', 'The Doubt Djinn', 176, 'Every book contradicts the next.'),
  (11, 'The Mountain of Hardship', 'Trials', 'The Suffering Giant', 202, 'Every step uphill. No summit visible.'),
  (12, 'The River of Regret', 'Past sins', 'The Guilt Wraith', 233, 'It flows backward. Always backward.'),
  (13, 'The Forest of Envy', 'Hasad', 'The Green-Eyed Shade', 268, 'Every tree bears fruit you cannot reach.'),
  (14, 'The Tower of Show-Off', 'Riya', 'The Two-Faced Lord', 308, 'Mirrors on every wall.'),
  (15, 'The Pit of Despair', 'Hopelessness', 'The Despair Fiend', 354, 'The bottom is deeper than you think.'),
  (16, 'The Hall of Gossip', 'Ghiba', 'The Forked-Tongue Demon', 407, 'Whispers about everyone but you.'),
  (17, 'The Chamber of Secrets', 'Hidden sins', 'The Shadow Spy', 468, 'Your own heart, exposed.'),
  (18, 'The Forge of Power Lust', 'Tyranny', 'The Iron Tyrant', 539, 'Where kings are made and broken.'),
  (19, 'The Swamp of Sloth', 'Deep laziness', 'The Bog Beast', 620, 'Every step sinks.'),
  (20, 'The Cliffs of Fear', 'Anxiety', 'The Terror Hawk', 713, 'One wrong step. One long fall.'),
  (21, 'The Desert of Thirst', 'Spiritual dryness', 'The Bone Dry Djinn', 820, 'No water for miles. No dhikr for days.'),
  (22, 'The Labyrinth of Confusion', 'Misguidance', 'The Mind Bender', 943, 'Every path leads back.'),
  (23, 'The Court of Injustice', 'Oppression', 'The Unjust Vizier', 1084, 'The verdict is already written.'),
  (24, 'The Fire of Hatred', 'Grudges', 'The Burning Khan', 1247, 'Old flames never die here.'),
  (25, 'The Mirror of Vanity', 'Vanity', 'The Glass Demon', 1434, 'You love what you see. That is the trap.'),
  (26, 'The Vault of Addiction', 'Drugs, porn, gambling', 'The Chain Master', 1649, 'The chains are gold. That''s the trick.'),
  (27, 'The Hive of Distraction', 'Endless scrolling', 'The Swarm Queen', 1896, 'A million notifications. None important.'),
  (28, 'The Stage of Fame', 'Seeking fame', 'The Masked Idol', 2180, 'Applause fades. The mask stays.'),
  (29, 'The Den of Betrayal', 'Dishonesty', 'The Oath Breaker', 2507, 'Every promise here was a lie.'),
  (30, 'The Well of Whisperers', 'Deep waswas', 'The Whispering Well', 2883, 'Look down. It looks back.'),
  (31, 'The Battlefield of Excuses', '"Tomorrow"', 'The Tomorrow Titan', 3315, 'Bones of every good intention.'),
  (32, 'The Crypt of Dead Hearts', 'Hard hearts', 'The Ashen King', 3812, 'Where feeling goes to die.'),
  (33, 'The Wasteland of Waste', 'Time-wasting', 'The Hour Eater', 4384, 'You had 24 hours. It took all of them.'),
  (34, 'The Chasm of Separation', 'Broken ties', 'The Severer', 5042, 'Family on one side. You on the other.'),
  (35, 'The Temple of False Gods', 'Shirk-adjacent', 'The Idol Colossus', 5798, 'You built it yourself.'),
  (36, 'The Cage of Comfort', 'Comfort zone', 'The Soft Jailer', 6668, 'The bars are made of pillows.'),
  (37, 'The Storm of Panic', 'Overwhelm', 'The Chaos Djinn', 7668, 'Every direction is the wrong one.'),
  (38, 'The Frost of Cold Hearts', 'Apathy', 'The Ice Sheikh', 8818, 'You stopped caring. That was the point.'),
  (39, 'The Web of Lies', 'Deception', 'The Weaver', 10141, 'The first lie was yours.'),
  (40, 'The Pit of Arrogance', 'Deep pride', 'The Fallen Prince', 11662, 'Look how far you have fallen. And still proud.'),
  (41, 'The Fort of Stubbornness', 'Refusing advice', 'The Iron Skull', 13411, 'You know better than everyone. Everyone.'),
  (42, 'The Sea of Doubts', 'Disbelief', 'The Wave Wraith', 15423, 'Every wave is a question you can''t answer.'),
  (43, 'The Hall of Mirrors', 'Self-deception', 'The Illusion Master', 17736, 'Which one is really you?'),
  (44, 'The Forge of Anger', 'Deep rage', 'The Rage Smith', 20396, 'He hammers grudges into weapons.'),
  (45, 'The Nest of Backbiters', 'Ghiba fortress', 'The Tongue Collector', 23456, 'He keeps every word you said.'),
  (46, 'The Maze of Waswas', 'Endless whispers', 'The Echo Demon', 26974, 'Your own voice, mocking you.'),
  (47, 'The Throne of Dunya', 'Worldly love', 'The Dunya Queen', 31020, 'She is beautiful and she is leaving.'),
  (48, 'The Chasm of Kibr', 'Grand arrogance', 'The Kibr Behemoth', 35673, 'He grows with every praise you accept.'),
  (49, 'The Tomb of Hearts', 'Spiritual death', 'The Grave Warden', 41024, 'Your heart is buried here. Find it.'),
  (50, 'The Forest of Fitnah', 'Tribulation', 'The Fitnah Beast', 47178, 'Every branch is a test.'),
  (51, 'The Storm of Nafs', 'Inner battle', 'The Nafs Tempest', 54255, 'The storm is not outside. It never was.'),
  (52, 'The Cave of Riya', 'Hidden shirk', 'The Silent Showman', 62393, 'Nobody is watching. That''s the test.'),
  (53, 'The Arena of Ego', 'Self-worship', 'The Ego Champion', 71752, 'The crowd is you. The judge is you.'),
  (54, 'The Lake of Regret', 'Sorrow', 'The Weeping Djinn', 82515, 'Every tear you didn''t cry is here.'),
  (55, 'The Forge of Whispers', 'Shaytan forge', 'The Whisper Smith', 94892, 'This is where doubts are made.'),
  (56, 'The Bridge of No Return', 'Point of no return', 'The Bridge Keeper', 109126, 'Cross. Don''t look back.'),
  (57, 'The Army of Iblis', 'First soldiers', 'The Vanguard General', 125495, 'They are not like the ones before.'),
  (58, 'The Fortress of Smoke', 'Deception HQ', 'The Smoke Lord', 144319, 'It looks like everything you ever wanted.'),
  (59, 'The Throne Room of Waswas', 'Whisper HQ', 'The Grand Whisperer', 165967, 'The whisper is now a roar.'),
  (60, 'The Court of the Fallen', 'Fallen jinn', 'The Fallen Vizier', 190862, 'They fell. They remember falling.'),
  (61, 'The Fire of the Fallen', 'Hellfire-adjacent', 'The Flame Khan', 219491, 'You feel the heat. That''s not imagination.'),
  (62, 'The Council of Shadows', 'Iblis advisors', 'The Shadow Council', 252415, 'Six voices. One agenda.'),
  (63, 'The Gate of Iblis', 'Final gate', 'The Gate Warden', 290277, 'Beyond this: no return.'),
  (64, 'The Plain of Final Battle', 'Pre-final', 'The Last General', 333819, 'Your ancestors fought here. So will you.'),
  (65, 'The Throne Approach', 'Iblis approach', 'The Champion of Iblis', 383892, 'His greatest warrior. Your final test.'),
  (66, 'The Throne of Iblis', 'FINAL', 'IBLIS', 999999999999999999, 'He has waited since the beginning of time. For you.')
